const holdInvoiceOperation = `-- name: HoldInvoiceOperation :execrows
UPDATE invoice_operations
SET status = 'HELD',
    held_until = $1,
    updated_at = $2,
    version = version + 1
WHERE id = $3
  AND status IN ('READY', 'RETRY_SCHEDULED')
`

type HoldInvoiceOperationParams struct {
	HeldUntil *time.Time         `db:"held_until" json:"held_until"`
	Now       pgtype.Timestamptz `db:"now" json:"now"`
	ID        int64              `db:"id" json:"id"`
}

// J08 READY／RETRY_SCHEDULED → HELD（買家送出付款後修改，M6 R03 的 `HELD CAS rows=1` 守衛）。
// held_until = now + 60s 由呼叫端傳入。chk_invop_held_pair 是雙向等式 ⇒ 兩欄同一句寫。
// ⚠️ 述詞刻意**不含 SENDING**：已經在打 AMEGO 的那一筆攔不下來（rows=0 ⇒ R03 不成立，
//
//	correction 改走 R04 作廢重開）。這正是 R03「operation 仍可被 HELD」那個守衛的實作。
//
// HELD 不在兩支 worker 的候選集合裡（next_attempt_at 不動），靠 ⑪ 掃回。
func (q *Queries) HoldInvoiceOperation(ctx context.Context, arg HoldInvoiceOperationParams) (int64, error) {
	result, err := q.db.Exec(ctx, holdInvoiceOperation, arg.HeldUntil, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

