const markInvoiceOperationDone = `-- name: MarkInvoiceOperationDone :execrows
UPDATE invoice_operations
SET status = 'SUCCEEDED', completed_at = $1,
    updated_at = $1, version = version + 1
WHERE id = $2 AND status = 'SENDING'
`

type MarkInvoiceOperationDoneParams struct {
	Now *time.Time `db:"now" json:"now"`
	ID  int64      `db:"id" json:"id"`
}

// ③ 完成。`AND status = 'SENDING'` 這道守衛是 §4.5.6 的 P/M 分類能成立的關鍵：
//
//	P/M 類的 ProcessFunc 會先在自己的交易內把 status 寫成終態（FAILED_PERMANENT /
//	SELLER_ACTION_REQUIRED / FAILED_UNKNOWN…）再回 nil，pkg/outbox 收到 nil 之後一定會呼叫
//	MarkDone。沒有這道守衛，MarkDone 會把「永久失敗」蓋成 SUCCEEDED，而且不報錯、不留痕。
//	有守衛時它 rows=0，什麼都不做。
func (q *Queries) MarkInvoiceOperationDone(ctx context.Context, arg MarkInvoiceOperationDoneParams) (int64, error) {
	result, err := q.db.Exec(ctx, markInvoiceOperationDone, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markInvoiceOperationFailed = `-- name: MarkInvoiceOperationFailed :execrows
UPDATE invoice_operations
SET status = 'FAILED_PERMANENT', last_error = $1,
    completed_at = $2, updated_at = $2, version = version + 1
WHERE id = $3 AND status IN ('SENDING', 'RETRY_SCHEDULED')
`

type MarkInvoiceOperationFailedParams struct {
	LastError *string    `db:"last_error" json:"last_error"`
	Now       *time.Time `db:"now" json:"now"`
	ID        int64      `db:"id" json:"id"`
}

// ④ 終結（attempt_count 達 max_attempts 時由 pkg/outbox 呼叫）。同樣守狀態，
//
//	不覆蓋 ProcessFunc 已經寫定的終態。
func (q *Queries) MarkInvoiceOperationFailed(ctx context.Context, arg MarkInvoiceOperationFailedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markInvoiceOperationFailed, arg.LastError, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markInvoiceOperationFailedWithProviderResult = `-- name: MarkInvoiceOperationFailedWithProviderResult :execrows
UPDATE invoice_operations
SET status = 'FAILED_PERMANENT',
    last_error = $1,
    provider_code = $2,
    provider_message = $3,
    completed_at = $4, updated_at = $4, version = version + 1
WHERE id = $5 AND status IN ('SENDING', 'RETRY_SCHEDULED')
`

type MarkInvoiceOperationFailedWithProviderResultParams struct {
	LastError       *string    `db:"last_error" json:"last_error"`
	ProviderCode    *string    `db:"provider_code" json:"provider_code"`
	ProviderMessage *string    `db:"provider_message" json:"provider_message"`
	Now             *time.Time `db:"now" json:"now"`
	ID              int64      `db:"id" json:"id"`
}

// ④' 終結，**同時保存 provider 的原話**（#3082，DEC-20260904-120527 選 A）。
//
// 🔴 與 ④ 分成兩句而不是把 provider 欄加進 ④：④ 的呼叫者是 pkg/outbox
//
//	（重試預算用完），它手上**沒有** provider 回應——那時候硬塞兩個 NULL 進去
//	會把先前某一次真的有 code 的記錄洗掉。本句給「這一次就是 provider 明確拒絕」
//	的呼叫者用。
//
// 在此之前 provider_code／provider_message **從未被任何路徑寫入**：
//
//	MarkFailed 只寫 last_error，而 MarkOperationProviderResult 那支只服務 J32。
//	後果是 ADM 的服務商往來看不到碼與訊息，只能去讀 last_error 的自由文字。
func (q *Queries) MarkInvoiceOperationFailedWithProviderResult(ctx context.Context, arg MarkInvoiceOperationFailedWithProviderResultParams) (int64, error) {
	result, err := q.db.Exec(ctx, markInvoiceOperationFailedWithProviderResult,
		arg.LastError,
		arg.ProviderCode,
		arg.ProviderMessage,
		arg.Now,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markInvoiceOperationResolvedExternally = `-- name: MarkInvoiceOperationResolvedExternally :execrows
UPDATE invoice_operations o
SET status = 'RESOLVED_EXTERNALLY',
    completed_at = $1,
    updated_at = $1,
    version = version + 1
WHERE o.id = $2
  AND o.version = $3
  AND (
    o.status = 'MANUAL_PROCESS_ALLOWED'
    OR (o.status = 'NOT_APPLICABLE' AND EXISTS (
          SELECT 1 FROM invoice_documents d
          WHERE d.id = o.document_id
            AND d.fulfillment_mode IN ('SELLER_SELF_ISSUE', 'LEGACY_MANUAL')))
  )
`

type MarkInvoiceOperationResolvedExternallyParams struct {
	Now             *time.Time `db:"now" json:"now"`
	ID              int64      `db:"id" json:"id"`
	ExpectedVersion int64      `db:"expected_version" json:"expected_version"`
}

// J30 MANUAL_PROCESS_ALLOWED → RESOLVED_EXTERNALLY（賣家回報號碼，端點 62）。終態。
// 守衛「號碼格式合法；provider_invoice_no 必須留空」落在 invoice_documents 那一側
//
//	（chk_invdoc_external_no_shape ＋ chk_invdoc_external_excl），本句只守狀態。
//	兩邊必須同一交易：只轉 operation 不轉 document，賣家 S08 會同時看到「已由賣家開立」
//	與「處理中」。
//
// 🔴 version CAS 不可省：端點 56／62 的 expectedVersion 是 §6.1.0(10) 的必填欄，而
//
//	「必填」只有寫進述詞才是保證。少了它，應用層那句 if 是純 TOCTOU——兩個分頁同時送出
//	時各自讀到舊版本、各自通過，第二筆才被 status 述詞擋掉（那是巧合不是設計），
//	而若第一筆改的是別的欄位就完全擋不住。
//
// 🔴 **allowed-from 加 NOT_APPLICABLE，但只限兩個 mode**（2026-09-05，DEC-20260905-221900 選 A）。
//
//	這條邊在設計書 §7.3.2 的 J 表裡沒有編號，因為它原本不存在；它是 §7.3.1
//	「SELLER_SELF_ISSUE / LEGACY_MANUAL 的合法 status 三值」那一列在 operation 側的對應。
//
// ⚠️ 它推翻了 §7.3.2 末段「終態只有四個」裡的 NOT_APPLICABLE 那一個
//
//	—— 對這兩個 mode 而言它不再是終態。**但兩處 FailOpen* 的正面清單不需要改**：
//	那份清單列的是「provider 停用時該被打成 FAILED_PERMANENT 的狀態」，
//	NOT_APPLICABLE 不在裡面是對的（那些 operation 從來不打 provider）。
//	885 行那句用 NOT IN 列終態，NOT_APPLICABLE 仍算已了結，也是對的
//	（回報前它確實沒有待辦）。實查兩處皆不受影響。
//
// 🔴 **mode 條件靠 EXISTS 查 document**，不放在呼叫端：NOT_APPLICABLE 也涵蓋
//
//	AMEGO_AUTO 的零元訂單／切點前訂單，那些不該開放回報。守衛放在這一句才擋得住
//	未來新增的呼叫端。
func (q *Queries) MarkInvoiceOperationResolvedExternally(ctx context.Context, arg MarkInvoiceOperationResolvedExternallyParams) (int64, error) {
	result, err := q.db.Exec(ctx, markInvoiceOperationResolvedExternally, arg.Now, arg.ID, arg.ExpectedVersion)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markInvoiceOperationRetryExhausted = `-- name: MarkInvoiceOperationRetryExhausted :execrows
UPDATE invoice_operations
SET status = 'FAILED_RETRY_EXHAUSTED',
    last_error = $1,
    completed_at = $2,
    updated_at = $2,
    version = version + 1
WHERE id = $3
  AND status = 'RETRY_SCHEDULED'
`

type MarkInvoiceOperationRetryExhaustedParams struct {
	LastError *string    `db:"last_error" json:"last_error"`
	Now       *time.Time `db:"now" json:"now"`
	ID        int64      `db:"id" json:"id"`
}

// J14 RETRY_SCHEDULED → FAILED_RETRY_EXHAUSTED（attempt_count 達 MaxAttempts）。
// 🔴 **不可沿用 ④ MarkInvoiceOperationFailed**：那一句固定寫 FAILED_PERMANENT，而 §7.3.2
//
//	把 FAILED_* 拆成三個的唯一理由就是「ADM 按下重試安不安全」必須由狀態本身回答：
//	  FAILED_PERMANENT       重試必然再失敗（統編錯、金額不平）⇒ 要求先修正資料（J18）
//	  FAILED_RETRY_EXHAUSTED 重試是安全的（暫時性錯誤，只是預算用完）⇒ 直接重置計數（J19）
//	寫錯值 ⇒ 一筆本來按一下就好的失敗，被要求「先修正資料」而其實沒有資料可修。
//
// outbox invoice.issue_failed（P2，failureClass=RETRY_EXHAUSTED；ISSUE 以外的 operation_type
//
//	改發 P7）由呼叫端在同一交易內寫進 invoice_outbox_events。
func (q *Queries) MarkInvoiceOperationRetryExhausted(ctx context.Context, arg MarkInvoiceOperationRetryExhaustedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markInvoiceOperationRetryExhausted, arg.LastError, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markInvoiceOperationSellerActionRequired = `-- name: MarkInvoiceOperationSellerActionRequired :execrows
UPDATE invoice_operations
SET status = 'SELLER_ACTION_REQUIRED',
    provider_code = $1,
    provider_message = $2,
    last_error = $3,
    updated_at = $4,
    version = version + 1
WHERE id = $5
  AND status = 'SENDING'
`

type MarkInvoiceOperationSellerActionRequiredParams struct {
	ProviderCode    *string            `db:"provider_code" json:"provider_code"`
	ProviderMessage *string            `db:"provider_message" json:"provider_message"`
	LastError       *string            `db:"last_error" json:"last_error"`
	Now             pgtype.Timestamptz `db:"now" json:"now"`
	ID              int64              `db:"id" json:"id"`
}

// J32 SENDING → SELLER_ACTION_REQUIRED（PERMANENT 中「賣家法定前置未完成」子類；3040111 字軌不足）。
// 與 J11（→ FAILED_PERMANENT）分開是刻意的：兩者的錯誤分類同為 PERMANENT，但一個要通知
//
//	賣家去財政部配字軌、一個要通知 ADM 改資料——行動指引完全相反。
//
// SELLER_ACTION_REQUIRED **不在**兩支 worker 的任何候選集合裡（撈起來只會空轉並燒掉 attempt）；
//
//	它不是永久旗標的唯一理由是 J33（INV.trk 偵測字軌恢復）與 J34（ADM 重試）兩條出邊
//	——刪掉它們，卡住的票就再也回不來，而且無告警。
//
// next_attempt_at 刻意不動（它不在任何候選述詞內，寫了也沒有讀者）。
func (q *Queries) MarkInvoiceOperationSellerActionRequired(ctx context.Context, arg MarkInvoiceOperationSellerActionRequiredParams) (int64, error) {
	result, err := q.db.Exec(ctx, markInvoiceOperationSellerActionRequired,
		arg.ProviderCode,
		arg.ProviderMessage,
		arg.LastError,
		arg.Now,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markInvoiceOperationWaitingConfirmation = `-- name: MarkInvoiceOperationWaitingConfirmation :execrows
UPDATE invoice_operations
SET status = 'WAITING_CONFIRMATION',
    unknown_result = true,
    unknown_since = COALESCE(unknown_since, $1),
    next_attempt_at = $2,
    provider_code = $3,
    provider_message = $4,
    last_error = $5,
    updated_at = $1,
    version = version + 1
WHERE id = $6
  AND status IN ('SENDING', 'PROVIDER_STATUS_RECHECK')
`

type MarkInvoiceOperationWaitingConfirmationParams struct {
	Now             pgtype.Timestamptz `db:"now" json:"now"`
	NextAttemptAt   pgtype.Timestamptz `db:"next_attempt_at" json:"next_attempt_at"`
	ProviderCode    *string            `db:"provider_code" json:"provider_code"`
	ProviderMessage *string            `db:"provider_message" json:"provider_message"`
	LastError       *string            `db:"last_error" json:"last_error"`
	ID              int64              `db:"id" json:"id"`
}

// J13 SENDING → WAITING_CONFIRMATION（逾時／連線中斷／JSON 解析失敗／code 分類 = UNKNOWN）。
// chk_invop_unknown_pair 是雙向等式 ⇒ unknown_result 與 unknown_since 必須同一句寫。
// unknown_since 是**事實時間戳**，也是重查退避階梯的分桶依據（§7.5.4 第 1 條）——
//
//	崩潰重來也不會變，這正是這條路不用計數器的理由。之後 ⑨⑩ 都刻意不重寫它。
//
// ⚠️ **不發 MQ**：invoice.issue.pending_confirmation 不在 §6.3 的 P1–P12 內。發到沒有 binding
//
//	的 routing key 會靜默消失、不進 DLQ、不報錯。「結果未明」是純內部觀測面，落點是
//	invoice_operation_unknown 指標與告警階梯；真的需要通知賣家時走 J17 的 P7。
//
// 轉出後這一列離開 INV.op 的候選集合、落進 INV.rc 的（兩組狀態集合互斥＝I-55）。
//
// 🔴 allowed-from **含 PROVIDER_STATUS_RECHECK**，因為本句有**兩個**進入點：
//
//	① INV.op 送出後結果未明（status=SENDING）—— 原本唯一被考慮到的那個
//	② INV.rc 的 ConfirmVoid／ConfirmAllowance 查不到結果、要繼續等（J31）
//	   —— 那時 ClaimInvoiceRecheck 已經把 status 蓋成 PROVIDER_STATUS_RECHECK
//
// 少了 ② 的後果（dev 第 3 輪實測）：scheduleVoidRecheck／scheduleAllowanceRecheck
// 呼叫本句必然 rows=0，而呼叫端把 rows 丟給 `_` ⇒ 完全無聲。兩個具體傷害：
//
//	(a) **退避階梯整條失效**：狀態沒回到 WAITING_CONFIRMATION、next_attempt_at 也沒被
//	    改成階梯值，那一列只被 ClaimInvoiceRecheck 的 60s 租約推著走
//	    ⇒ 每 60 秒打一次 AMEGO，而設計是 30s→1m→2m→5m→10m→30m 逐步退避
//	    ⇒ 對 provider 的請求量在最壞情況放大約 30 倍。
//	(b) **unknown_since 從不寫入**（COALESCE 那一句沒被執行到）⇒ 對「沒有經過
//	    SENDING → WAITING_CONFIRMATION 就進 recheck」的列（例如 ADM 取消後從
//	    CANCEL_REQUESTED 被 claim 進來的），`now − unknown_since` 恆為 0
//	    ⇒ **24h give-up 永遠到不了**。實測 operation 7501222107859124224 即此形。
//
// COALESCE 在兩個進入點下都正確：第一次進入未明狀態時起算，之後不重寫
//
//	—— 那正是退避階梯與 24h 門檻共用的事實時間戳（⑨⑩ 刻意不重寫它，同源）。
func (q *Queries) MarkInvoiceOperationWaitingConfirmation(ctx context.Context, arg MarkInvoiceOperationWaitingConfirmationParams) (int64, error) {
	result, err := q.db.Exec(ctx, markInvoiceOperationWaitingConfirmation,
		arg.Now,
		arg.NextAttemptAt,
		arg.ProviderCode,
		arg.ProviderMessage,
		arg.LastError,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markInvoiceRecheckResolved = `-- name: MarkInvoiceRecheckResolved :execrows
UPDATE invoice_operations
SET status = $1,
    next_attempt_at = $2,
    unknown_result = false,
    unknown_since = NULL,
    recheck_list_page = 0,
    provider_code = $3,
    provider_message = $4,
    completed_at = $5,
    cancel_evidence_kind = COALESCE($6, cancel_evidence_kind),
    cancel_confirmed_at = COALESCE($7, cancel_confirmed_at),
    updated_at = $8,
    version = version + 1
WHERE id = $9 AND status = 'PROVIDER_STATUS_RECHECK'
`

type MarkInvoiceRecheckResolvedParams struct {
	NextStatus         string             `db:"next_status" json:"next_status"`
	NextAttemptAt      pgtype.Timestamptz `db:"next_attempt_at" json:"next_attempt_at"`
	ProviderCode       *string            `db:"provider_code" json:"provider_code"`
	ProviderMessage    *string            `db:"provider_message" json:"provider_message"`
	CompletedAt        *time.Time         `db:"completed_at" json:"completed_at"`
	CancelEvidenceKind *string            `db:"cancel_evidence_kind" json:"cancel_evidence_kind"`
	CancelConfirmedAt  *time.Time         `db:"cancel_confirmed_at" json:"cancel_confirmed_at"`
	Now                pgtype.Timestamptz `db:"now" json:"now"`
	ID                 int64              `db:"id" json:"id"`
}

// ⑧ 對帳**有確定結果**的落點（§4.3.3 支數表）：
//
//	  J23 SUCCEEDED           —— invoice_query code=0 或 invoice_list 比對到，回填號碼
//	  J24 CANCELLED_BY_ADMIN  —— code=71 且有 ADM 取消在途
//	  J25 RETRY_SCHEDULED     —— code=71 且無 ADM 取消在途：確認未開立、可安全補送，把列還給 INV.op
//	這三個由呼叫端依判別式決定後以 next_status 傳入（§7.5.4 第 2 條：
//	cancel_requested_at IS NOT NULL AND cancel_confirmed_at IS NULL ⇒ ADM 取消在途）。
//	⚠️ 不得沿用 ③ MarkInvoiceOperationDone：它固定寫 SUCCEEDED，會蓋掉另外兩個落點（§4.6 W-04）。
//
// 結果已確定 ⇒ unknown_result / unknown_since 一起清空（chk_invop_unknown_pair 是雙向等式，
//
//	只清一個會當場 23514）。J25 的 completed_at 必須傳 NULL（它不是終態）。
//
// recheck_list_page 歸零：invoice_list 的分頁游標在命中或翻到空頁時重設（§7.5.4 第 3 條）。
// J24 專屬的兩個欄位（J23／J25 一律傳 NULL）：
//
//	cancel_evidence_kind = PROVIDER_QUERY_71 —— chk_invop_admin_cancel_needs_confirm
//	  放行 J24 的**唯一**依據。J24 沒有第二個人（cancel_confirmed_by 恆為 NULL），
//	  不帶這個值就必定 23514。
//	cancel_confirmed_at —— 不寫的話「ADM 取消在途」判別式
//	  （cancel_requested_at IS NOT NULL AND cancel_confirmed_at IS NULL）永遠成立，
//	  資料上這筆會一直看起來像還沒處理完。
//
// J23 的語意是「取消請求被回絕」⇒ 兩欄傳 NULL 正確：那次取消確實沒有生效。
// 🔴 兩欄用 **COALESCE(narg, 原值)** 而不是無條件覆寫：J23／J25 也走這一支，
//
//	而端點 54（A4 解鎖）可能已經在 cancel_evidence_kind 上寫了值
//	——J27 會把 CANCEL_BLOCKED_UNKNOWN 推回 PROVIDER_STATUS_RECHECK，那之後
//	J23／J25 都可能發生 ⇒ 無條件覆寫會把那份證據**靜默抹掉**。
//	「傳 NULL＝不動它」與「傳 NULL＝清空」在這裡是完全不同的兩件事。
func (q *Queries) MarkInvoiceRecheckResolved(ctx context.Context, arg MarkInvoiceRecheckResolvedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markInvoiceRecheckResolved,
		arg.NextStatus,
		arg.NextAttemptAt,
		arg.ProviderCode,
		arg.ProviderMessage,
		arg.CompletedAt,
		arg.CancelEvidenceKind,
		arg.CancelConfirmedAt,
		arg.Now,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markInvoiceRecheckUnresolved = `-- name: MarkInvoiceRecheckUnresolved :execrows
UPDATE invoice_operations
SET status = $1,
    next_attempt_at = $2,
    recheck_list_page = 0,
    provider_code = $3,
    provider_message = $4,
    last_error = $5,
    updated_at = $6,
    version = version + 1
WHERE id = $7 AND status = 'PROVIDER_STATUS_RECHECK'
`

type MarkInvoiceRecheckUnresolvedParams struct {
	NextStatus      string             `db:"next_status" json:"next_status"`
	NextAttemptAt   pgtype.Timestamptz `db:"next_attempt_at" json:"next_attempt_at"`
	ProviderCode    *string            `db:"provider_code" json:"provider_code"`
	ProviderMessage *string            `db:"provider_message" json:"provider_message"`
	LastError       *string            `db:"last_error" json:"last_error"`
	Now             pgtype.Timestamptz `db:"now" json:"now"`
	ID              int64              `db:"id" json:"id"`
}

// ⑨ 對帳**仍不確定**且要換狀態的落點：
//
//	J26 CANCEL_BLOCKED_UNKNOWN —— code=51 或再次逾時，且有 ADM 取消在途；永不自動終結
//	J17 FAILED_UNKNOWN         —— 無 ADM 取消在途且 now − unknown_since > 24h
//
// ⚠️ 刻意不叫 MarkInvoiceRecheckExhausted：INV.rc **沒有「次數耗盡」這條路**，
//
//	叫 Exhausted 會誘導實作者去接一個 MaxAttempts（§4.3.3）。
//
// ⚠️ unknown_since **不重寫**（J26「unknown_since 保留」）：它是退避階梯的分桶依據，
//
//	而且是事實時間戳——崩潰重來也不會變，這正是不用計數器的理由（§7.5.4 第 1 條）。
//	unknown_result 同樣維持 true，否則 chk_invop_unknown_pair 與保留下來的 unknown_since 打架。
//
// ⚠️ 也不得沿用 ④ MarkInvoiceOperationFailed：FAILED_PERMANENT 對「查不到」是錯的分類，
//
//	會讓一張補得回來的發票停在終態。
func (q *Queries) MarkInvoiceRecheckUnresolved(ctx context.Context, arg MarkInvoiceRecheckUnresolvedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markInvoiceRecheckUnresolved,
		arg.NextStatus,
		arg.NextAttemptAt,
		arg.ProviderCode,
		arg.ProviderMessage,
		arg.LastError,
		arg.Now,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const promoteCreatedInvoiceOperation = `-- name: PromoteCreatedInvoiceOperation :execrows
UPDATE invoice_operations
SET status = $1,
    next_attempt_at = $2,
    updated_at = $3,
    version = version + 1
WHERE id = $4
  AND status = 'CREATED'
`

type PromoteCreatedInvoiceOperationParams struct {
	NextStatus    string             `db:"next_status" json:"next_status"`
	NextAttemptAt pgtype.Timestamptz `db:"next_attempt_at" json:"next_attempt_at"`
	Now           pgtype.Timestamptz `db:"now" json:"now"`
	ID            int64              `db:"id" json:"id"`
}

// J02／J03／J04：CREATED → READY／AWAITING_TRIGGER／NOT_APPLICABLE，**建列的同一事務內判定**。
// 三條邊共用一句的條件：來源狀態相同、SET 形狀相同，差別只在目標值與 next_attempt_at：
//
//	J02 READY            issue_not_before <= now  ⇒ next_attempt_at = now
//	J03 AWAITING_TRIGGER issue_not_before >  now  ⇒ next_attempt_at = issue_not_before
//	J04 NOT_APPLICABLE   決策樹落在四個 reason 之一 ⇒ next_attempt_at 隨便給都不會被撈
//
// ⚠️ J04 的「寫 not_applicable_reason」落在 **invoice_documents**，本表沒有那個欄位。
// ⚠️ AWAITING_TRIGGER 不在任何一支 worker 的候選集合裡；把它推回 READY 的唯一執行者是
//
//	⑫ PromoteDueInvoiceOperationTriggers，而它讀的是 invoice_documents.issue_not_before
//	這個**權威值**，不是本句寫進去的副本。
func (q *Queries) PromoteCreatedInvoiceOperation(ctx context.Context, arg PromoteCreatedInvoiceOperationParams) (int64, error) {
	result, err := q.db.Exec(ctx, promoteCreatedInvoiceOperation,
		arg.NextStatus,
		arg.NextAttemptAt,
		arg.Now,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const promoteDueInvoiceOperationTriggers = `-- name: PromoteDueInvoiceOperationTriggers :execrows
UPDATE invoice_operations o
SET status = 'READY', updated_at = $1
FROM invoice_documents d
WHERE d.id = o.document_id
  AND o.status = 'AWAITING_TRIGGER'
  AND d.issue_not_before <= $1
`

// ⑫ AWAITING_TRIGGER 的 promote（J05）。與 ⑪ 同形態：RunOnce 前置、集合式、不需要 claim。
// 述詞讀 invoice_documents.issue_not_before（**權威值**，§5.1.5），不讀 operation 自己的
//
//	next_attempt_at：後者只是 J03 建列當下複製過去的一份副本。拿副本當觸發條件，任何一條未來
//	會寫 next_attempt_at 的路徑（延後開票的 ADM 改期、人工調整）都會讓它**提早開票**——而提早
//	開票在稅務上不可回復。讀權威欄則最壞只是晚一輪（10 秒）。
//
// ⚠️ 這一句 join 不牴觸「候選 SQL 必須在單表上排序」：那條講的是帶 ORDER BY 的
//
//	FetchDueInvoiceOperations（排序鍵在 join 另一邊 ⇒ 索引用不上）。本句無 ORDER BY，
//	且 AWAITING_TRIGGER 在 Phase 1 恆為空集合。
//
// 少了這一支，**J05 沒有任何元件會執行**；Phase 1 因 issue_not_before 恆為即刻而不會顯現
//
//	⇒ 這是潛伏缺陷，一旦啟用「延後開票」，整批訂單靜默不開票。
func (q *Queries) PromoteDueInvoiceOperationTriggers(ctx context.Context, now pgtype.Timestamptz) (int64, error) {
	result, err := q.db.Exec(ctx, promoteDueInvoiceOperationTriggers, now)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const promoteSellerActionRequiredOperations = `-- name: PromoteSellerActionRequiredOperations :execrows
UPDATE invoice_operations o
SET status = 'READY',
    attempt_count = 0,
    next_attempt_at = $1,
    updated_at = $1,
    version = o.version + 1
FROM invoice_documents d
WHERE d.id = o.document_id
  AND o.status = 'SELLER_ACTION_REQUIRED'
  AND d.issuer_id = $2
`

type PromoteSellerActionRequiredOperationsParams struct {
	Now      pgtype.Timestamptz `db:"now" json:"now"`
	IssuerID int64              `db:"issuer_id" json:"issuer_id"`
}

// J33 SELLER_ACTION_REQUIRED → READY（INV.trk 查到該 issuer 字軌餘量恢復）。
// **集合式 UPDATE、無外部副作用、不需要 claim**（外部呼叫是 INV.trk 本職的字軌查詢，
//
//	已在前一步做完），形態同 ⑪ ReleaseExpiredInvoiceOperationHolds／⑫ PromoteDueInvoiceOperationTriggers
//	——《多副本排程搶佔規範》例外 A：推出候選集合的寫入就是狀態轉移本身，第二個副本 rows=0。
//
// ⚠️ invoice_operations **沒有 issuer_id 欄**：operation 的擁有者判定一律經 invoice_documents
//
//	join（invoice_documents.sql 檔頭已寫過同一件事）。字軌是 per-issuer 的資源，所以述詞
//	必須帶 issuer，否則一個賣家配到字軌會把全平台卡住的票一起放行。
//
// attempt_count 歸零：字軌不足期間燒掉的次數不該算在真正的重試預算上。
// 本句無 ORDER BY ⇒ 不牴觸「候選 SQL 必須在單表上排序」（那條講的是帶 ORDER BY 的 ①⑥）。
// ⚠️ `o.version` 的 alias 不是裝飾：UPDATE ... FROM 的 SET **右手邊**會同時解析 target 與 FROM
//
//	兩張表，而 invoice_operations 與 invoice_documents **都有 version 欄** ⇒ 寫成
//	`version = version + 1` 會在執行時 `column reference "version" is ambiguous`（42702）。
//	sqlc generate 過、go build 過、單元測試過——只有真的送到 PostgreSQL 才會現形。
func (q *Queries) PromoteSellerActionRequiredOperations(ctx context.Context, arg PromoteSellerActionRequiredOperationsParams) (int64, error) {
	result, err := q.db.Exec(ctx, promoteSellerActionRequiredOperations, arg.Now, arg.IssuerID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const releaseExpiredInvoiceOperationHolds = `-- name: ReleaseExpiredInvoiceOperationHolds :execrows
UPDATE invoice_operations
SET status = 'READY', held_until = NULL, updated_at = $1
WHERE status = 'HELD' AND held_until <= $1
`

// ⑪ HELD 釋放。放在 INV.op 的 RunOnce **前置步驟**，不另開排程、不需要 claim：
//
//	集合式單句 UPDATE、無外部副作用（不打 AMEGO、不發 MQ），第二個副本 rows=0。
//
// `held_until = NULL` 不可省：§5.1.8 的 chk_invop_held_pair
//
//	CHECK (("status" = 'HELD') = ("held_until" IS NOT NULL)) 是雙向等式 ⇒ 只改 status
//	不清 held_until，這一句**每一輪都以 23514 整批失敗**——而它跑在候選查詢之前
//	⇒ 連帶讓整支 INV.op 該輪一筆都送不出去。
func (q *Queries) ReleaseExpiredInvoiceOperationHolds(ctx context.Context, now pgtype.Timestamptz) (int64, error) {
	result, err := q.db.Exec(ctx, releaseExpiredInvoiceOperationHolds, now)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const releaseInvoiceOperationHold = `-- name: ReleaseInvoiceOperationHold :execrows
UPDATE invoice_operations
SET status          = 'READY',
    held_until      = NULL,
    next_attempt_at = $1,
    updated_at      = $1,
    version         = version + 1
WHERE id = $2
  AND status = 'HELD'
`

type ReleaseInvoiceOperationHoldParams struct {
	Now pgtype.Timestamptz `db:"now" json:"now"`
	ID  int64              `db:"id" json:"id"`
}

// §7.3.5 R03 的收尾：把 HELD 放回 READY，**同一事務內**，不等租約到期。
//
// 🔴 少了這一句不會報錯、不會有測試紅，只是那張發票有 60 秒開不出去：
//
//	HELD 不在兩支 worker 的候選集合裡（見 HoldInvoiceOperation 的註解），
//	要等 ReleaseExpiredInvoiceOperationHolds 掃回才動得了。
//
// 🔴 held_until = NULL 不可省：chk_invop_held_pair 是雙向等式，只改 status 不清
//
//	held_until 會 23514（同 CancelInvoiceOperationBeforeIssue 的教訓）。
//
// next_attempt_at 設為 now：R03 改完快照就該立刻送出，不要沿用 HELD 之前的排程。
func (q *Queries) ReleaseInvoiceOperationHold(ctx context.Context, arg ReleaseInvoiceOperationHoldParams) (int64, error) {
	result, err := q.db.Exec(ctx, releaseInvoiceOperationHold, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const requestInvoiceOperationCancel = `-- name: RequestInvoiceOperationCancel :execrows
UPDATE invoice_operations
SET status = 'CANCEL_REQUESTED',
    cancel_requested_by = $1,
    cancel_requested_at = $2,
    cancel_reason_code = $3,
    cancel_reason = $4,
    next_attempt_at = $2,
    updated_at = $2,
    version = version + 1
WHERE id = $5
  AND status IN ('READY', 'RETRY_SCHEDULED', 'FAILED_PERMANENT',
                 'FAILED_RETRY_EXHAUSTED', 'SELLER_ACTION_REQUIRED')
  AND version = $6
`

type RequestInvoiceOperationCancelParams struct {
	CancelRequestedBy *int64     `db:"cancel_requested_by" json:"cancel_requested_by"`
	Now               *time.Time `db:"now" json:"now"`
	CancelReasonCode  *string    `db:"cancel_reason_code" json:"cancel_reason_code"`
	CancelReason      *string    `db:"cancel_reason" json:"cancel_reason"`
	ID                int64      `db:"id" json:"id"`
	ExpectedVersion   int64      `db:"expected_version" json:"expected_version"`
}

// J21 READY／RETRY_SCHEDULED／FAILED_PERMANENT／FAILED_RETRY_EXHAUSTED／SELLER_ACTION_REQUIRED
//
//	→ CANCEL_REQUESTED（ADM 取消，端點 53）。五個來源逐字等於轉換表那一列。
//
// 🔴 `next_attempt_at = now` 在**同一句**內不可省：ADM 的強制最終查詢是同步路徑，中途崩潰時
//
//	這一筆會停在 CANCEL_REQUESTED 而沒有任何人接手。寫了它，INV.rc 下一輪立刻接手
//	（CANCEL_REQUESTED 在 ⑥ 的候選述詞內）；不寫，從 RETRY_SCHEDULED 取消的那筆會沿用舊退避，
//	最壞延遲一整個週期才被接手。
//
// chk_invop_cancel_pair 是雙向等式 (cancel_requested_by IS NULL) = (cancel_requested_at IS NULL)
//
//	⇒ 兩欄同一句寫。
//
// ⚠️ 「ADM 取消在途」的判別式（J17／J24／J25／J26／J31 共用）是
//
//	`cancel_requested_at IS NOT NULL AND cancel_confirmed_at IS NULL` ——本句寫的就是那個
//	判別式的左半。claim 會把來源狀態蓋成 PROVIDER_STATUS_RECHECK，所以落點不能靠來源狀態判。
func (q *Queries) RequestInvoiceOperationCancel(ctx context.Context, arg RequestInvoiceOperationCancelParams) (int64, error) {
	result, err := q.db.Exec(ctx, requestInvoiceOperationCancel,
		arg.CancelRequestedBy,
		arg.Now,
		arg.CancelReasonCode,
		arg.CancelReason,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateInvoiceOperationAttempt = `-- name: UpdateInvoiceOperationAttempt :exec
UPDATE invoice_operations
SET attempt_count = $1,
    next_attempt_at = $2,
    last_error = $3,
    status = 'RETRY_SCHEDULED',
    updated_at = $4,
    version = version + 1
WHERE id = $5
`

type UpdateInvoiceOperationAttemptParams struct {
	AttemptCount  int32              `db:"attempt_count" json:"attempt_count"`
	NextAttemptAt pgtype.Timestamptz `db:"next_attempt_at" json:"next_attempt_at"`
	LastError     *string            `db:"last_error" json:"last_error"`
	Now           pgtype.Timestamptz `db:"now" json:"now"`
	ID            int64              `db:"id" json:"id"`
}

// ⑤ 退避重排。這是租約欄 next_attempt_at 的第二個寫入者，而且是刻意的
//
//	（《多副本排程搶佔規範》§三 第 7 點已明文承認 backoff 寫入的正當性）：
//	它只會在本副本仍持有租約時執行，把「租約」換成「下次可執行時間」。
//
// ⚠️ 本句無條件 SET status='RETRY_SCHEDULED'（第 1 組的候選狀態）⇒ INV.rc **絕對不可以**沿用它，
//
//	否則一筆「查完仍未確定」的列下一輪就被 INV.op 撈走並真的重送一次 f0401 ⇒ 重複開票
//	（§4.6 W-03）。INV.rc 的對應落點是 ⑩ UpdateInvoiceRecheckAttempt。
func (q *Queries) UpdateInvoiceOperationAttempt(ctx context.Context, arg UpdateInvoiceOperationAttemptParams) error {
	_, err := q.db.Exec(ctx, updateInvoiceOperationAttempt,
		arg.AttemptCount,
		arg.NextAttemptAt,
		arg.LastError,
		arg.Now,
		arg.ID,
	)
	return err
}

const updateInvoiceRecheckAttempt = `-- name: UpdateInvoiceRecheckAttempt :execrows
UPDATE invoice_operations
SET status = $1,
    next_attempt_at = $2,
    recheck_list_page = $3,
    provider_code = $4,
    provider_message = $5,
    updated_at = $6,
    version = version + 1
WHERE id = $7 AND status = 'PROVIDER_STATUS_RECHECK'
`

type UpdateInvoiceRecheckAttemptParams struct {
	NextStatus      string             `db:"next_status" json:"next_status"`
	NextAttemptAt   pgtype.Timestamptz `db:"next_attempt_at" json:"next_attempt_at"`
	RecheckListPage int16              `db:"recheck_list_page" json:"recheck_list_page"`
	ProviderCode    *string            `db:"provider_code" json:"provider_code"`
	ProviderMessage *string            `db:"provider_message" json:"provider_message"`
	Now             pgtype.Timestamptz `db:"now" json:"now"`
	ID              int64              `db:"id" json:"id"`
}

// ⑩ 仍不確定且**留在重查迴圈**：
//
//	J31 WAITING_CONFIRMATION      —— 無 ADM 取消在途且 now − unknown_since <= 24h
//	自轉移 PROVIDER_STATUS_RECHECK —— 留在原地等下一輪
//
// next_attempt_at 由呼叫端算好傳入：階梯位置由事實時間戳 unknown_since 推導
//
//	（30s → 1m → 2m → 5m → 10m → 30m 觸頂；≥24h 之後 +6h／+24h／+7d），**不另設計數器**。
//
// recheck_list_page 由呼叫端傳入：每翻一頁 +1、翻到空頁或命中重設為 0。
//
//	這是 60s 租約唯一的成立理由——沒有游標就得在一次 claim 內翻完 N 頁，最壞 N × 20s 無上界。
//
// unknown_since 不重寫（同 ⑨）。
func (q *Queries) UpdateInvoiceRecheckAttempt(ctx context.Context, arg UpdateInvoiceRecheckAttemptParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateInvoiceRecheckAttempt,
		arg.NextStatus,
		arg.NextAttemptAt,
		arg.RecheckListPage,
		arg.ProviderCode,
		arg.ProviderMessage,
		arg.Now,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
